import { getDefaultValueType, setTarget, visualElementStore } from 'motion';
import { motion, useAnimation } from 'motion/react';

import { cn } from '@/lib/utils';

export interface HugeiconsHatGlassesIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}
interface HugeiconsHatGlassesIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}
const HAT_VARIANTS: Variants = {
  normal: {
    rotate: 0,
    y: 0,
  },
  animate: {
    rotate: [0, -4, 2, 0],
    y: [0, -3, 1, 0],
    transition: {
      duration: 0.5,
      ease: 'easeOut',
      times: [0, 0.35, 0.65, 1],
    },
  },
};
const GLASSES_VARIANTS: Variants = {
  normal: {
    scale: 1,
    y: 0,
  },
  animate: {
    scale: [1, 0.96, 1],
    y: [0, 1, 0],
    transition: {
      delay: 0.28,
      duration: 0.32,
      ease: 'easeInOut',
    },
  },
};
const HugeiconsHatGlassesIcon = forwardRef<
  HugeiconsHatGlassesIconHandle,
  HugeiconsHatGlassesIconProps
>(({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
  const controls = useAnimation();
  const isControlledRef = useRef(false);
  const {
    rootRef: iconRootRef,
    reduceDefinition,
    ...iconAccessibility
  } = useIconAccessibility(ref, () => {
    isControlledRef.current = ref != null;
    return {
      startAnimation: () => controls.start('animate'),
      stopAnimation: () => controls.start('normal'),
    };
  }, [controls]);
  const handleMouseEnter = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (!isControlledRef.current) {
        controls.start('animate');
      }
      void e;
    },
    [controls]
  );
  const handleMouseLeave = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (!isControlledRef.current) {
        controls.start('normal');
      }
      void e;
    },
    [controls]
  );
  return (
    <div
      className={cn(className)}
      {...props}
      ref={iconRootRef}
      onMouseEnter={(event) => {
        if (!iconAccessibility.controlled && !iconAccessibility.reduced) {
          handleMouseEnter(event);
        }
        onMouseEnter?.(event);
      }}
      onMouseLeave={(event) => {
        if (!iconAccessibility.controlled) {
          handleMouseLeave(event);
        }
        onMouseLeave?.(event);
      }}
      onFocus={(event) => {
        if (!iconAccessibility.controlled && !iconAccessibility.reduced) {
          iconAccessibility.startAnimation();
        }
        props.onFocus?.(event);
      }}
      onBlur={(event) => {
        if (!iconAccessibility.controlled) {
          iconAccessibility.stopAnimation();
        }
        props.onBlur?.(event);
      }}
    >
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
        focusable="false"
        style={{ overflow: 'visible' }}
      >
        <motion.g
          animate={reduceDefinition(controls)}
          initial="normal"
          style={{ originX: '12px', originY: '12px' }}
          variants={HAT_VARIANTS}
        >
          <path
            d="M4.5 11.75L5.95607 6.02568C6.2363 4.92402 6.37641 4.3732 6.63691 4.03341C7.10346 3.42485 7.86014 3.13788 8.59632 3.29029C9.00738 3.37539 9.45841 3.70202 10.3605 4.35529C10.833 4.69747 11.0692 4.86855 11.3172 4.96174C11.7583 5.12751 12.2417 5.12751 12.6828 4.96174C12.9308 4.86855 13.167 4.69747 13.6395 4.35529C14.5416 3.70202 14.9926 3.37539 15.4037 3.29029C16.1399 3.13788 16.8965 3.42485 17.3631 4.03341C17.6236 4.37319 17.7637 4.92403 18.0439 6.02568L19.5 11.75"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
          />
          <path
            d="M5.5 9H18.4962"
